/* Case-study data, carried over unchanged from the previous site. */
const SECTIONS=[
 "Project Overview","Business Problem","Learner Problem","Target Audience","Learning Objectives",
 "Instructional Strategy","Content Architecture","Storyboard Samples","Interaction Design Decisions",
 "Assessment Strategy","Performance Support Assets","Accessibility Considerations","Prototype Screens",
 "Success Metrics","Reflection & Lessons Learned"];

/* reusable visual builders */
function frame(num,roleTxt,onscreen,narration,interaction,bars="w90"){
 return `<div class="frame"><div class="screen"><span class="fnum">${num}</span>
   <div class="mock-bar w70"></div><div class="mock-bar ${bars}"></div><div class="mock-bar w40"></div>
   <div class="mock-btn"><i></i><i class="alt"></i></div></div>
   <div class="meta"><div class="role">${roleTxt}</div>
   <p><b style="color:var(--text)">On-screen:</b> ${onscreen}</p>
   <p><b style="color:var(--text)">Narration:</b> ${narration}</p>
   <p><b style="color:var(--text)">Interaction:</b> ${interaction}</p></div></div>`;}

const PROJECTS={
 "p-lms":{
  title:"AI Workflow Quest",
  sub:"A guided, branching simulation that moves a non-technical employee from AI user to AI supervisor — built on one thesis: don't simulate the agent, simulate the decision points.",
  facts:[["Role","ID + LXD + front-end build"],["Audience","Non-technical AI users"],["Domain","AI enablement · responsible use"],["Mode","Web simulation · branching · single-file"]],
  thumbClass:"t-lms",
  body:{
   "Project Overview":`<div style="display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px"><a class="btn btn-primary" href="ai-workflow-quest.html" target="_blank" rel="noopener">&#9654; Open the live simulation</a></div><p>A built, interactive learning simulation that takes a non-technical employee through four authored scenarios — from a first AI delegation to supervising an automation chain — teaching them to <b>own the decision points</b> a human must keep. The governing idea: don't try to fake the AI, simulate the moments where judgment matters.</p><div class="row3"><div class="mini-card"><div class="ic">&#129517;</div><h4>User &#8594; supervisor</h4><p>The learner's role visibly flips from "using AI" to "supervising AI" at the pivotal approval.</p></div><div class="mini-card"><div class="ic">&#127807;</div><h4>Decide, don't watch</h4><p>Deterministic branches at a few load-bearing moments; consequence is shown, not described — and always recoverable.</p></div><div class="mini-card"><div class="ic">&#128202;</div><h4>Reads back real choices</h4><p>The closing report is computed from what the learner actually did — no hardcoded "demonstrated".</p></div></div>`,
   "Business Problem":`<p>Organizations handed employees AI assistants faster than they taught the judgment to supervise them. The risk isn't a bad draft — it's an <b>unsupervised action</b>: an AI that sends, schedules, or shares before a human checks. Rubber-stamped approvals and context-blind automations leak data and erode trust.</p><p><b>The metric at risk:</b> safe, confident AI adoption. The gap is supervision behavior, not tool familiarity.</p>`,
   "Learner Problem":`<ul class="obj"><li><span class="lvl">Trust</span><span><b>Output looks finished, so it gets approved</b> — learners rubber-stamp without opening the draft.</span></li><li><span class="lvl">Blind spots</span><span><b>The dangerous moment is invisible</b> — the same output is safe or harmful depending on a context only a human checks (internal vs. external recipient).</span></li><li><span class="lvl">Model</span><span><b>No mental model of think vs. act</b> — which steps are reversible reasoning, which touch a person or a record.</span></li></ul>`,
   "Target Audience":`<p>Primary: <b>non-technical knowledge workers</b> beginning to use AI assistants for real work. Secondary: <b>enablement leads</b> who need adoption that is responsible and defensible, not just frequent.</p>`,
   "Learning Objectives":`<p>Behavioral objectives, scoped to the simulation:</p><ul class="obj"><li><span class="lvl">Understand</span><span>Distinguish a model-only draft from a real tool action that touches a person or record.</span></li><li><span class="lvl app">Apply</span><span>Decompose a task into think (reasoning) and act (irreversible) steps.</span></li><li><span class="lvl eval">Evaluate</span><span>Catch a context flaw before approving — the right action to the wrong recipient.</span></li><li><span class="lvl eval">Supervise</span><span>Verify, correct, and re-approve — and keep supervising on the next gate, not just once.</span></li><li><span class="lvl app">Decide</span><span>Choose what to automate vs. where to keep a human verification point.</span></li></ul>`,
   "Instructional Strategy":`<div class="row2"><div class="mini-card"><div class="ic">&#127919;</div><h4>Simulate decisions, not the agent</h4><p>Authored branches concentrate at a few load-bearing moments; everything between is compressed and railed.</p></div><div class="mini-card"><div class="ic">&#9889;</div><h4>Just-in-time concepts</h4><p>One new idea surfaces at its moment of relevance — including the word "agent," which only earns its place once the learner needs it.</p></div><div class="mini-card"><div class="ic">&#127807;</div><h4>Consequence, recoverable</h4><p>The leak is experienced, then rewound — a mistake to learn from, never a punitive dead end.</p></div><div class="mini-card"><div class="ic">&#128483;</div><h4>Two voices, one screen</h4><p>A warm human coach (serif on paper) and a terse system layer (mono on dark) make the invisible visible without overload.</p></div></div>`,
   "Content Architecture":`<p>Four scenarios across seven capability layers, with fidelity matched to teaching value.</p><div class="arch"><div class="arch-tier"><div class="at"><span class="badge">S1&#8211;S2</span> Foundations (full build)</div><div class="mods"><span class="mod">First delegation</span><span class="mod">Model vs. tool call</span><span class="mod">Think / act decomposition</span></div></div><div class="arch-tier"><div class="at"><span class="badge">S3</span> The approval that mattered &#8212; centerpiece</div><div class="mods"><span class="mod">Review or rubber-stamp</span><span class="mod">Leak &#8594; rewind &#8594; repair</span><span class="mod">Second gate &#183; role flips</span></div></div><div class="arch-tier"><div class="at"><span class="badge">S4</span> Orchestration &#8212; storyboarded (honest scope)</div><div class="mods"><span class="mod">Who does what</span><span class="mod">Where to keep a verification point</span></div></div></div>`,
   "Storyboard Samples":`<div class="story-grid">${frame("S1 · First delegation","Contrast pair","A model-only draft sits beside the same task run as a real tool call, with an animated lookup trace.","Coach voice frames why the difference matters.","Connect the tool, watch the trace, then a quick check.")}${frame("S3 · The approval that mattered","Decision point",'The AI drafts a correct message to the wrong "Shanda" — internal vs. external. Approve, reject, or edit.',"No narration at the decision — the choice carries the weight.","Approve to see the leak and rewind; or edit recipient, claim, and context to repair.","w70")}</div>`,
   "Interaction Design Decisions":`<ul class="obj"><li><span class="lvl">Why</span><span><b>Rubber-stamping is captured silently</b> — approving without opening the draft changes the consequence, without the UI scolding the learner.</span></li><li><span class="lvl">Why</span><span><b>The flaw is compound</b> — the output is only dangerous because the recipient is external; the lesson is context, not typos.</span></li><li><span class="lvl">Why</span><span><b>A second approval gate</b> proves supervision is a habit that persists, not a one-time catch.</span></li><li><span class="lvl">Why</span><span><b>Role flips on success</b> — the status changes from "user" to "supervisor" at the moment the behavior changes.</span></li></ul>`,
   "Assessment Strategy":`<p>Assessment is the behavior itself — the closing report is computed from real choices, never hardcoded.</p><table class="tbl"><tr><th>Captured behavior</th><th>Signal</th><th>From</th></tr><tr><td><b>Checks work before approving</b></td><td class="tag-l">Verify</td><td>Did the learner open the draft?</td></tr><tr><td><b>Recognizes risk</b></td><td class="tag-l">Judgment</td><td>Caught the external recipient / sensitive context.</td></tr><tr><td><b>Breaks work into steps</b></td><td class="tag-l">Decompose</td><td>Think / act tagging accuracy.</td></tr><tr><td><b>Supervises AI</b></td><td class="tag-l">Transfer</td><td>Repaired and re-approved on the second gate.</td></tr></table>`,
   "Performance Support Assets":`<div class="row3"><div class="mini-card"><div class="ic">&#129534;</div><h4>Behavior report</h4><p>A debrief that reflects the learner's actual decisions back to them — and to a facilitator.</p></div><div class="mini-card"><div class="ic">&#128257;</div><h4>Rewind to repair</h4><p>Built-in recovery turns the mistake into the lesson, then lets the learner fix it.</p></div><div class="mini-card"><div class="ic">&#128228;</div><h4>Pilot instrumentation</h4><p>Captured signals are structured for an export / debrief view (planned) to support a real pilot.</p></div></div>`,
   "Accessibility Considerations":`<p>Accessibility is the documented next iteration on this build — stated honestly rather than overclaimed.</p><div class="a11y"><div><span class="ck">&#10003;</span> AA-passing colour contrast across all text on the paper and system surfaces.</div><div><span class="ck">&#10003;</span> Real buttons for primary actions; semantic structure and a page language set.</div><div><span class="ck" style="color:var(--amber)">&#9711;</span> In progress: keyboard + focus-visible for the remaining choice rows.</div><div><span class="ck" style="color:var(--amber)">&#9711;</span> In progress: aria-live on the coach, incident, and report regions.</div><div><span class="ck" style="color:var(--amber)">&#9711;</span> In progress: prefers-reduced-motion for the animated traces.</div></div><p style="font-size:14px;color:var(--muted)">Claiming accessibility expertise means being honest about what is and isn't done yet — the keyboard, screen-reader, and reduced-motion pass is scoped and next.</p>`,
   "Prototype Screens":`<div class="proto"><div class="device"><div class="scr"><div class="hd"><span class="dt">Coach</span><span class="dp">S1</span></div><div class="choice">Model-only draft</div><div class="choice sel">Same task as a tool call &#10003;</div></div><div class="cap">Contrast pair</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Approval</span><span class="dp">S3</span></div><div class="choice">Approve now</div><div class="choice sel">Open &amp; check the recipient &#10003;</div><div class="choice">Reject</div></div><div class="cap">The decision that mattered</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Report</span><span class="dp">Debrief</span></div><div class="choice sel">Recognizes risk &#10003;</div><div class="choice sel">Supervises AI &#10003;</div></div><div class="cap">Computed from real choices</div></div></div>`,
   "Success Metrics":`<div class="metric-grid"><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">human checkpoints correctly kept</div><div class="k">Kirkpatrick L2</div></div><div class="mc"><div class="mtgt">&#8595; reduce</div><div class="l">rubber-stamped approvals</div><div class="k">L3 &#183; behavior</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">context-risk caught before send</div><div class="k">L3</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">appropriate-automation decisions</div><div class="k">L4</div></div></div><div class="note"><b>&#9656;</b> Design targets — arrows show the direction of success. No results are claimed; figures pending a pilot.</div>`,
   "Reflection & Lessons Learned":`<div class="reflect"><p><b>What worked:</b> Simulating the decision points instead of the agent kept the build small and the teaching sharp — the leak-and-rewind on Scenario 3 carries more learning than any explanation could.</p><p><b>What I'd change:</b> The keyboard, screen-reader, and reduced-motion pass is the honest next step; the piece earns its accessibility claim only once that ships.</p><p><b>The transferable lesson:</b> Responsible-AI training is a supervision-behavior problem. Make the invisible decision visible, let the consequence be felt and recovered, and measure the behavior — not the click.</p></div>`
  }},
 "p-safe":{
  title:"SiteReady — Scissor Lift Safety Awareness",
  sub:"A mobile-first awareness micro-module and a printable pre-use job aid that help new operators and site personnel recognize scissor-lift hazards and make the right first move — Stop, Fix, or Proceed.",
  facts:[["Role","ID + LXD + front-end build"],["Audience","New operators & site personnel"],["Domain","Industrial safety · awareness"],["Mode","Web module · Job aid · SCORM-ready"]],
  thumbClass:"t-safe",
  body:{
   "Project Overview":`<div style="display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px"><a class="btn btn-primary" href="deploy/index.html" target="_blank" rel="noopener">▶ Open the live module</a><a class="btn btn-ghost" href="SiteReady-ScissorLift-PreUseCard.html" target="_blank" rel="noopener">⬇ Pre-Use Card (printable job aid)</a></div><p>A built, deployable <b>awareness micro-module</b> on scissor-lift safety, paired with a one-page <b>pre-use card</b> for the point of work. It teaches hazard recognition and the right first action through scroll-based microlearning, a randomized Stop / Fix / Proceed scenario check, and spaced-retrieval flashcards — then hands the worker a printable job aid to carry to the floor.</p><div class="row3"><div class="mini-card"><div class="ic">👁️</div><h4>Recognize</h4><p>Tip-over, struck-by, falls, and overhead/electrical hazards — dual-coded with isometric and scenario art.</p></div><div class="mini-card"><div class="ic">🌿</div><h4>Decide</h4><p>Low-stakes Stop / Fix / Proceed practice, drawn 3-of-5, with corrective retries and no shaming.</p></div><div class="mini-card"><div class="ic">📇</div><h4>Transfer</h4><p>A printable pre-use checklist + sign-off puts the job aid at the moment of work.</p></div></div>`,
   "Business Problem":`<p>Annual classroom safety training satisfies a compliance checkbox but doesn't reliably transfer to behavior in the field, and scissor lifts remain a leading source of aerial-lift incidents — tip-overs, falls, and electrocutions. Sites need awareness that is <b>faster to deliver, clearer for a mixed-literacy crew, and actually carried to the floor</b>.</p><p><b>The metric at risk:</b> incident and near-miss rate, and the human and financial cost behind it. A transfer-and-behavior problem, not a content-volume problem.</p>`,
   "Learner Problem":`<ul class="obj"><li><span class="lvl">Context</span><span><b>Learning happens off-site; the hazard is on-site</b> — a transfer gap between the classroom and the platform.</span></li><li><span class="lvl">Literacy</span><span><b>Mixed reading levels and languages</b> make text-heavy slides inaccessible to part of the crew.</span></li><li><span class="lvl">Relevance</span><span><b>Generic content</b> loses experienced operators; the module stays specific to the machine in front of them.</span></li></ul>`,
   "Target Audience":`<p>Primary: <b>new scissor-lift operators and general site personnel</b> — often deskless, mobile-first, multilingual, with varied literacy and little spare time. Secondary: <b>supervisors</b> who run pre-use checks and hold stop-work authority. Designed for a phone, gloves, and a few spare minutes.</p>`,
   "Learning Objectives":`<p>Awareness-level objectives, written to be observable:</p><ul class="obj"><li><span class="lvl eval">Recognize</span><span>Identify the main scissor-lift hazards — tip-over, struck-by, falls, and overhead/electrical contact.</span></li><li><span class="lvl app">Apply</span><span>Run a pre-use walk-around and red-tag a machine that fails it.</span></li><li><span class="lvl eval">Locate</span><span>Find both E-Stops and the emergency-descent rescue path before elevating.</span></li><li><span class="lvl eval">Decide</span><span>Choose the right first action in a hazard scenario — Stop, Fix, or Proceed.</span></li></ul><p style="font-size:14px;color:var(--muted)">Scoped as <b>awareness</b> — explicitly not OSHA-authorized training, operator authorization, or a qualified-person evaluation.</p>`,
   "Instructional Strategy":`<div class="row2"><div class="mini-card"><div class="ic">🧠</div><h4>Behavior-based + dual coding</h4><p>Every rule pairs with a visual, one idea per screen, to cut cognitive load for a multilingual, lower-literacy crew.</p></div><div class="mini-card"><div class="ic">🌿</div><h4>Scenario decision practice</h4><p>Comic-style Stop / Fix / Proceed scenarios build judgment through consequence, not trivia.</p></div><div class="mini-card"><div class="ic">⚡</div><h4>Spaced retrieval</h4><p>An eight-card flashcard deck reinforces the rules with active recall.</p></div><div class="mini-card"><div class="ic">📇</div><h4>Performance support</h4><p>A printable pre-use card moves the job aid to the point of work — the L2→L3 bridge.</p></div></div>`,
   "Content Architecture":`<p>An <b>awareness layer</b>, kept visibly separate from the competency-support layer (hands-on training, a qualified-person evaluation, and employer authorization).</p><div class="arch"><div class="arch-tier"><div class="at"><span class="badge">Explain</span> Scroll micro-module (M0–M8)</div><div class="mods"><span class="mod">Anatomy</span><span class="mod">Pre-use walk-around</span><span class="mod">Tip-over</span><span class="mod">Danger zone</span><span class="mod">Overhead / 10 ft</span><span class="mod">E-Stops</span><span class="mod">Manual descent</span><span class="mod">Fall protection</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Apply</span> Scenario check + retrieval</div><div class="mods"><span class="mod">Stop / Fix / Proceed (3 of 5)</span><span class="mod">Flashcards (×8)</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Support</span> Point of work</div><div class="mods"><span class="mod">Printable pre-use card</span><span class="mod">Tag-out guidance</span><span class="mod">Sign-off fields</span></div></div></div>`,
   "Storyboard Samples":`<div class="story-grid">${frame("M3 · Tip-over","Dual-coded rule","Side-by-side stable vs. tip-over states with 'Firm · Flat · Level' as the single takeaway.","Plain-language, one idea per screen.","Scroll activates the unstable state; a pulsing ring marks the risk.")}${frame("Scenario · E-Stop","Stop / Fix / Proceed","The platform lurches and the controls go dead. Three options, no obvious tell.","No narration — the decision carries the weight.","Pick an option → corrective feedback; the correct answer reveals the safe-outcome panel.","w70")}</div>`,
   "Interaction Design Decisions":`<ul class="obj"><li><span class="lvl">Why</span><span><b>Focus-lock scroll</b> spotlights one module at a time to control cognitive load.</span></li><li><span class="lvl">Why</span><span><b>Numbered anatomy callouts</b> (hover, tap, or keyboard focus) link the diagram to the parts list via dual coding.</span></li><li><span class="lvl">Why</span><span><b>Consequence-based feedback</b> in the scenario check — corrective retries, no score, no shaming — so judgment transfers.</span></li><li><span class="lvl">Why</span><span><b>Reduced-motion fallback</b> renders every module linearly for motion-sensitive users and assistive tech.</span></li></ul>`,
   "Assessment Strategy":`<p>Low-stakes and behavior-focused — the goal is the right move at the right moment, not a grade.</p><table class="tbl"><tr><th>Assessment</th><th>Type</th><th>Objective</th><th>Measures</th></tr><tr><td><b>Scenario check</b></td><td class="tag-l">Scenario</td><td>Decide</td><td>Stop / Fix / Proceed on 3 of 5 randomized hazards, with corrective retries.</td></tr><tr><td><b>Flashcard deck</b></td><td class="tag-l">Retrieval</td><td>Recognize</td><td>Active recall of the eight rules; self-paced review.</td></tr><tr><td><b>Pre-use card</b></td><td class="tag-l">Transfer</td><td>Apply</td><td>On-the-job walk-around + sign-off (an L3 behavior signal).</td></tr></table>`,
   "Performance Support Assets":`<div style="margin:0 0 14px"><a class="btn btn-ghost" href="SiteReady-ScissorLift-PreUseCard.html" target="_blank" rel="noopener">⬇ Open the printable Pre-Use Card</a></div><div class="row3"><div class="mini-card"><div class="ic">📋</div><h4>Pre-use checklist</h4><p>One-page walk-around with sign-off for machine ID, operator, and supervisor.</p></div><div class="mini-card"><div class="ic">🟥</div><h4>Tag-out + stop-work</h4><p>Red-tag a failed machine; anyone can stop unsafe work, anytime, no penalty.</p></div><div class="mini-card"><div class="ic">🖨️</div><h4>Print-ready</h4><p>Dedicated print styles render a clean one-page PDF for the toolbox.</p></div></div>`,
   "Accessibility Considerations":`<div class="a11y"><div><span class="ck">✓</span> Skip link, semantic landmarks, and visible focus throughout.</div><div><span class="ck">✓</span> Reduced-motion mode renders all modules linearly.</div><div><span class="ck">✓</span> Scenario check is a labeled radiogroup with an aria-live result.</div><div><span class="ck">✓</span> Flashcards flip via keyboard (Enter / Space).</div><div><span class="ck">✓</span> Dual coding — never color or text alone — for low-literacy and multilingual readers.</div><div><span class="ck">✓</span> Single self-contained file; SCORM-ready for an LMS.</div></div>`,
   "Prototype Screens":`<div class="proto"><div class="device"><div class="scr"><div class="hd"><span class="dt">Walk-around</span><span class="dp">M2</span></div><div class="choice sel">☑ Guardrails solid, gate latches</div><div class="choice">☐ Test both control stations</div></div><div class="cap">Pre-use checklist</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">E-Stop</span><span class="dp">Scenario</span></div><div class="choice">Climb over the rail</div><div class="choice sel">Hit the Emergency Stop ✓</div><div class="choice">Keep operating</div></div><div class="cap">Stop / Fix / Proceed</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Rule 1</span><span class="dp">Deck</span></div><div class="choice">Where do you elevate?</div><div class="choice sel">Firm · Flat · Level ✓</div></div><div class="cap">Spaced-retrieval flashcard</div></div></div>`,
   "Success Metrics":`<div class="metric-grid"><div class="mc"><div class="mtgt">↑ improve</div><div class="l">module + scenario completion</div><div class="k">Kirkpatrick L2</div></div><div class="mc"><div class="mtgt">↑ improve</div><div class="l">pre-use card use on the floor</div><div class="k">L3 · behavior</div></div><div class="mc"><div class="mtgt">↑ improve</div><div class="l">near-miss reporting</div><div class="k">L3 · culture</div></div><div class="mc"><div class="mtgt">↓ reduce</div><div class="l">recordable incidents</div><div class="k">L4</div></div></div><div class="note"><b>▸</b> Awareness concept — arrows show the direction of success. No results are claimed; measured data and a baseline are added once captured.</div>`,
   "Reflection & Lessons Learned":`<div class="reflect"><p><b>What worked:</b> Keeping the awareness layer visibly separate from competency — and flagging every machine-specific claim <b style="color:var(--amber)">[VERIFY WITH SME]</b> — made the piece honest and defensible, which matters more than polish in a safety context.</p><p><b>What I'd change:</b> The eight takeaways drift slightly between the module and the pre-use card; I'd lock one canonical list and reuse it everywhere.</p><p><b>The transferable lesson:</b> Building the front-end myself meant the instructional intent survived all the way to the screen — dual coding, reduced-motion, and the point-of-work job aid were design decisions, not handoff casualties.</p></div>`
  }},
 
 "p-drive":{
  title:"Ohio DriveSmart Academy",
  sub:"An interactive driver-education prototype — eight lesson modules, illustrated flashcards, a Road-Test-Readiness gauge, and a guardrailed AI study coach — built in React with a server-side AI proxy. Educational concept, not a BMV-approved course.",
  facts:[["Role","ID + LXD + full-stack build"],["Audience","Ohio teen learner drivers"],["Domain","Driver education · responsible AI"],["Mode","React + Vite app · serverless AI"]],
  thumbClass:"t-drive",
  body:{
   "Project Overview":`<div style="display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px"><a class="btn btn-primary" href="https://ohio-drivesmart-academy.vercel.app/" target="_blank" rel="noopener">&#9654; Open the live app</a></div><p>A built React/Vite single-page app that teaches teen drivers through a <b>learn &#8594; see &#8594; decide &#8594; feedback &#8594; mastery</b> loop, with illustrated flashcards, an xAPI-style learning record, an accessibility panel, and <b>RoadGuide AI</b> — a guardrailed study coach whose API key stays server-side. Framed honestly as an educational concept, not an official or BMV-approved course.</p><div class="row3"><div class="mini-card"><div class="ic">&#129496;</div><h4>Decide, then learn</h4><p>Each module practices a real driving decision and gates progress on mastery, not seat time.</p></div><div class="mini-card"><div class="ic">&#129302;</div><h4>Guardrailed AI coach</h4><p>RoadGuide answers rules questions in plain English — never claims the learner is licensed; the key never reaches the browser.</p></div><div class="mini-card"><div class="ic">&#9855;</div><h4>Accessible by design</h4><p>Keyboard, focus, ARIA, reduce-motion, readable-font, larger-text and high-contrast toggles built in.</p></div></div>`,
   "Business Problem":`<p>Novice drivers crash at far higher rates than experienced ones, and a rules-test-prep product can lift pass rates without changing the outcome that matters — real-road judgment. Dry, text-heavy courses also lose a digital-native audience fast.</p><p><b>The metric at risk:</b> novice-driver decision-readiness and crash risk. Sourced framing only (CDC, NHTSA, NSC, IIHS, Ohio DPS/OSHP) — no invented numbers.</p>`,
   "Learner Problem":`<ul class="obj"><li><span class="lvl">Skill gap</span><span><b>Rules &#8800; judgment</b> — a learner can pass the written test and still freeze at a real hazard.</span></li><li><span class="lvl">Motivation</span><span><b>Dry content disengages teens</b> — a voluntary, young audience needs pace, feedback, and progress.</span></li><li><span class="lvl">Practice</span><span><b>No safe place to fail</b> — first real decisions otherwise happen at speed.</span></li></ul>`,
   "Target Audience":`<p>Primary: <b>Ohio teens (15&#8211;17)</b> on a temporary permit — mobile-native, low tolerance for friction, high response to feedback. Secondary: <b>parents and instructors</b> who supervise and review.</p>`,
   "Learning Objectives":`<ul class="obj"><li><span class="lvl">Recall</span><span>State Ohio road rules, signs, and right-of-way in context.</span></li><li><span class="lvl eval">Perceive</span><span>Detect a developing hazard in a driving scene.</span></li><li><span class="lvl eval">Decide</span><span>Choose the safe response under time pressure.</span></li><li><span class="lvl app">Apply</span><span>Transfer scanning and decision habits to supervised real practice.</span></li></ul>`,
   "Instructional Strategy":`<div class="row2"><div class="mini-card"><div class="ic">&#127807;</div><h4>Decision loop per module</h4><p>Learn &#8594; see &#8594; decide &#8594; feedback &#8594; mastery, with remediation when a concept is missed.</p></div><div class="mini-card"><div class="ic">&#127918;</div><h4>Mastery gating</h4><p>Progress reflects demonstrated skill, shown on a Road-Test-Readiness gauge that tops out at "Practice-ready."</p></div><div class="mini-card"><div class="ic">&#127183;</div><h4>Spaced flashcards</h4><p>Illustrated signs and markings reinforce recall between modules.</p></div><div class="mini-card"><div class="ic">&#129302;</div><h4>Just-in-time coach</h4><p>RoadGuide AI answers a learner's question at the moment of confusion, within strict guardrails.</p></div></div>`,
   "Content Architecture":`<p>A data-driven module system (eight built, scoped toward an 18-module curriculum), plus dashboard, flashcards, learning record, and a Documents page that holds the research and compliance basis.</p><div class="arch"><div class="arch-tier"><div class="at"><span class="badge">Learn</span> Eight lesson modules</div><div class="mods"><span class="mod">Signs &amp; signals</span><span class="mod">Right-of-way</span><span class="mod">Hazard scenarios</span><span class="mod">Mastery + remediation</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Practice</span> Recall &amp; coach</div><div class="mods"><span class="mod">Illustrated flashcards</span><span class="mod">RoadGuide AI</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Evidence</span> Records &amp; basis</div><div class="mods"><span class="mod">xAPI-style learning record</span><span class="mod">Readiness gauge</span><span class="mod">Documents (sources + liability)</span></div></div></div>`,
   "Storyboard Samples":`<div class="story-grid">${frame("Module · Decide","Scenario decision","A first-person intersection — an unprotected left, the gap closing. Go, wait, or creep forward.","Brief coaching after the choice, never a scolding.","Pick an option, then see the consequence and the safer read.")}${frame("RoadGuide · Coach","Guardrailed AI","A learner asks a rules question; the coach answers in plain English and never claims they are licensed.","Calm, short, plain language.","A server-side proxy keeps the API key off the browser.","w70")}</div>`,
   "Interaction Design Decisions":`<ul class="obj"><li><span class="lvl">Why</span><span><b>Readiness caps at "Practice-ready"</b> — the UI never implies the learner is licensed or legally ready.</span></li><li><span class="lvl">Why</span><span><b>The AI key stays server-side</b> — the browser calls a proxy, so the secret never ships in the bundle.</span></li><li><span class="lvl">Why</span><span><b>Feedback uses icon + text + colour</b> — never colour alone, so it reads for colour-blind users.</span></li><li><span class="lvl">Why</span><span><b>Reduce-motion is honoured</b> — animations respect the system setting and an in-app toggle.</span></li></ul>`,
   "Assessment Strategy":`<table class="tbl"><tr><th>Assessment</th><th>Type</th><th>Objective</th><th>Measures</th></tr><tr><td><b>Module mastery check</b></td><td class="tag-l">Mastery</td><td>Recall / Decide</td><td>Gates progress; triggers remediation on a miss.</td></tr><tr><td><b>Hazard scenario</b></td><td class="tag-l">Scenario</td><td>Perceive / Decide</td><td>Safe-choice rate under pressure.</td></tr><tr><td><b>Learning record</b></td><td class="tag-l">xAPI-style</td><td>Apply</td><td>Captured events shown on the record page (LRS-ready).</td></tr></table>`,
   "Performance Support Assets":`<div class="row3"><div class="mini-card"><div class="ic">&#129302;</div><h4>RoadGuide AI</h4><p>A guardrailed study coach for plain-English rules questions, on demand.</p></div><div class="mini-card"><div class="ic">&#127183;</div><h4>Flashcard deck</h4><p>Illustrated signs and pavement markings for spaced recall.</p></div><div class="mini-card"><div class="ic">&#128196;</div><h4>Documents page</h4><p>The research sources and a clear liability statement — compliance in the open.</p></div></div>`,
   "Accessibility Considerations":`<div class="a11y"><div><span class="ck">&#10003;</span> Full keyboard operability with visible focus throughout.</div><div><span class="ck">&#10003;</span> ARIA labels on controls; text equivalents for SVG diagrams and the readiness gauge.</div><div><span class="ck">&#10003;</span> Feedback is icon + text + colour — never colour alone.</div><div><span class="ck">&#10003;</span> Toggle panel: reduce-motion, plain-language, readable font (Atkinson Hyperlegible), larger text, high contrast.</div><div><span class="ck">&#10003;</span> prefers-reduced-motion honoured in CSS.</div><div><span class="ck">&#10003;</span> Compliance copy: educational concept only; readiness capped at "Practice-ready."</div></div>`,
   "Prototype Screens":`<div class="proto"><div class="device"><div class="scr"><div class="hd"><span class="dt">Dashboard</span><span class="dp">Readiness</span></div><div class="choice sel">Readiness: Practice-ready &#10003;</div><div class="choice">8 modules · mastery-gated</div></div><div class="cap">Readiness gauge</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Intersection</span><span class="dp">Decide</span></div><div class="choice">Go now</div><div class="choice sel">Wait for the gap &#10003;</div><div class="choice">Creep forward</div></div><div class="cap">Scenario decision</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">RoadGuide</span><span class="dp">AI coach</span></div><div class="choice">When do I yield here?</div><div class="choice sel">Plain-English answer &#10003;</div></div><div class="cap">Guardrailed coach</div></div></div>`,
   "Success Metrics":`<div class="metric-grid"><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">hazard-detection accuracy</div><div class="k">Kirkpatrick L2</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">safe-choice rate under pressure</div><div class="k">L2 · decision skill</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">voluntary practice sessions</div><div class="k">Engagement</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">module mastery completion</div><div class="k">L2</div></div></div><div class="note"><b>&#9656;</b> Design targets — arrows show the direction of success. No results are claimed; figures pending a pilot.</div>`,
   "Reflection & Lessons Learned":`<div class="reflect"><p><b>What worked:</b> Teaching judgment before rote rules, gated by mastery, gave the prototype a real spine — and a server-side AI proxy let me add an AI coach without ever exposing a key.</p><p><b>What I'd change:</b> State resets on reload; persisting progress and accessibility prefs in localStorage is the first enhancement — and persisting a11y prefs is itself a WCAG win.</p><p><b>The transferable lesson:</b> Responsible ed-tech is as much about what you refuse to claim — not "BMV-approved," not "licensed" — as about what you build.</p></div>`
  }},

 "p-aero":{
  title:"AeroMind — Drone Avionics Training Simulator",
  sub:"A browser-based 3D flight simulator that teaches new drone operators pitch, roll, yaw, throttle, telemetry literacy, and failsafe behavior — before they ever touch real hardware. Every stick input becomes a visible, explained physics lesson.",
  facts:[["Role","LXD + simulation design + 3D build"],["Audience","Student / first-time drone operators"],["Domain","Drone operation · safety habits"],["Mode","Web 3D sim · Three.js · single-file"]],
  thumbClass:"t-aero",
  body:{
   "Project Overview":`<div style="display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px"><a class="btn btn-primary" href="https://aeromind-flightlab.vercel.app/" target="_blank" rel="noopener">&#9654; Fly the live simulator</a><a class="btn btn-ghost" href="https://github.com/AkhilDhruva/AeroMind-FlightLab" target="_blank" rel="noopener">View source on GitHub</a></div><p>A built, playable 3D training simulator: a rendered quadcopter on a training field, a full telemetry HUD, twelve lesson modules, and a live <b>Input &#8594; Physics &#8594; Explanation</b> feed that narrates what just happened on every control input. Solid obstacles, procedural motor audio, gamepad support, and automatic Return-to-Home failsafes make safe habits feel like consequences, not rules. <b>Educational civilian flight-training simulation — not a real drone control system.</b></p><div class="row3"><div class="mini-card"><div class="ic">&#128737;</div><h4>Safety-first by design</h4><p>Smoothness is scored, not speed. Hard landings, collisions, and ignored warnings all cost the stability grade — and explain why.</p></div><div class="mini-card"><div class="ic">&#128202;</div><h4>Telemetry literacy</h4><p>Battery, GPS, signal, wind, heading, and mode are taught as things to <i>read</i>, with failure scenarios that make scanning them matter.</p></div><div class="mini-card"><div class="ic">&#129302;</div><h4>The sim explains itself</h4><p>Every input triggers a plain-language explanation of the physics it caused — tilt first, then movement.</p></div></div>`,
   "Business Problem":`<p>Consumer and commercial drones put real aircraft in untrained hands. The cost of a beginner's first mistakes — a fly-away, a crashed gimbal, an airspace violation — is paid in hardware, liability, and lost confidence. Flight schools and hobbyists need a way to build <b>correct control instincts and failsafe trust</b> before the first real battery is ever armed.</p><p><b>The metric at risk:</b> first-flight incident rate and training drop-off. The gap is operator readiness, not aircraft capability.</p>`,
   "Learner Problem":`<ul class="obj"><li><span class="lvl">Model</span><span><b>Controls are not intuitive</b> — a drone tilts before it moves, strafes without turning, and rotates without travelling. Beginners conflate pitch, roll, and yaw.</span></li><li><span class="lvl">Overload</span><span><b>The HUD reads as noise</b> — battery %, satellites, signal, and mode mean nothing until a scenario makes each one matter.</span></li><li><span class="lvl">Trust</span><span><b>Failsafes get fought</b> — untrained pilots panic and fight Return-to-Home instead of letting the aircraft recover itself.</span></li></ul>`,
   "Target Audience":`<p>First-time and student drone operators — teens to adults — flying consumer quadcopters; secondarily, instructors who want a zero-risk demonstration environment. Assumes no aviation background, no gamepad required (keyboard fully supported), and runs in any modern browser with no install.</p>`,
   "Learning Objectives":`<ul class="obj"><li><span class="lvl">Operate</span><span>Command pitch, roll, yaw, and throttle independently and in combination to fly a controlled circuit.</span></li><li><span class="lvl">Read</span><span>Interpret live telemetry — battery, GPS, signal, wind, mode — and act on warnings before they become emergencies.</span></li><li><span class="lvl">Decide</span><span>Choose the safe response to low battery, wind drift, GPS degradation, and signal loss, including yielding to Return-to-Home.</span></li><li><span class="lvl">Land</span><span>Execute soft, precise landings — the skill that ends every flight, rehearsed until it is graded clean.</span></li></ul>`,
   "Instructional Strategy":`<div class="row2"><div class="mini-card"><div class="ic">&#9889;</div><h4>One axis at a time</h4><p>Throttle &#8594; pitch &#8594; roll &#8594; yaw as isolated modules with physical targets (rings, gates, markers), then a combined sortie.</p></div><div class="mini-card"><div class="ic">&#128483;</div><h4>Explain at the moment of input</h4><p>The explanation feed fires on the stick movement itself — the physics lesson lands exactly when the learner caused it.</p></div><div class="mini-card"><div class="ic">&#127807;</div><h4>Consequence, not punishment</h4><p>Collisions bounce and cost score; emergencies auto-recover via RTH. Mistakes teach and are always recoverable with R.</p></div><div class="mini-card"><div class="ic">&#127918;</div><h4>Scenario-based failure drills</h4><p>Low battery, wind, weak GPS, and signal loss are playable emergencies with auto-detected objectives, not slides.</p></div></div>`,
   "Content Architecture":`<p>Twelve modules in a deliberate arc — anatomy first, single-axis control, integration, instrumentation, then emergencies.</p><div class="arch"><div class="arch-tier"><div class="at"><span class="badge">Know</span> The aircraft</div><div class="mods"><span class="mod">Anatomy (click-to-inspect)</span><span class="mod">Free Flight sandbox</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Control</span> One axis at a time</div><div class="mods"><span class="mod">Throttle</span><span class="mod">Pitch · rings</span><span class="mod">Roll · cone gate</span><span class="mod">Yaw · markers</span><span class="mod">Combined mission</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Read</span> Instruments</div><div class="mods"><span class="mod">Avionics &amp; telemetry</span><span class="mod">Precision landing</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Survive</span> Emergencies</div><div class="mods"><span class="mod">Low battery</span><span class="mod">Wind drift</span><span class="mod">Signal loss</span><span class="mod">GPS degraded</span></div></div></div>`,
   "Storyboard Samples":`<div class="story-grid">${frame("M02 · Pitch","Tilt, then move","The drone noses down as W is held; three glowing rings ahead at constant altitude.","'The rear rotors spin up, the nose dips, and the aircraft accelerates forward. Notice it tilts before it moves.'","Hold W through all three rings; each ring lights green and chimes on a clean pass.")}${frame("Scenario · Low battery","Failsafe handover","Battery hits 12% mid-flight; amber warning pill, alert tone, then RTH takes the sticks.","'Critical battery. The flight controller is flying the aircraft home — watch, don't fight the controls.'","Pilot input is locked out until the aircraft lands itself on the pad.","w80")}</div>`,
   "Interaction Design Decisions":`<ul class="obj"><li><span class="lvl">Why</span><span><b>The feed explains inputs, not outcomes</b> — firing on the stick edge ties cause to physics at the exact teachable moment.</span></li><li><span class="lvl">Why</span><span><b>RTH locks out the sticks</b> — fighting the failsafe is the classic beginner error, so the sim makes yielding the only option and says so.</span></li><li><span class="lvl">Why</span><span><b>Obstacles are solid</b> — flying through scenery teaches nothing; a bounce, a &#8722;10 score hit, and a damage explanation teach clearance.</span></li><li><span class="lvl">Why</span><span><b>Motor audio is throttle-linked and goes silent when idle</b> — sound carries information (load, spool-up, alerts), never ambience for its own sake.</span></li><li><span class="lvl">Why</span><span><b>Gamepad maps to a real transmitter</b> — left stick throttle/yaw, right stick pitch/roll, with live calibration bars and an adjustable deadzone.</span></li></ul>`,
   "Assessment Strategy":`<p>Continuous, behavioral, and explained — the grade is how you flew, not what you clicked.</p><table class="tbl"><tr><th>Assessment</th><th>Type</th><th>Objective</th><th>Measures</th></tr><tr><td><b>Auto-detected objectives</b></td><td class="tag-l">Performance</td><td>Operate / Decide</td><td>Mission steps detected from flight state — altitude held, rings passed, marker aligned, landed near pad.</td></tr><tr><td><b>Stability score</b></td><td class="tag-l">Continuous</td><td>Operate</td><td>Starts at 100; jerky input, hard landings, and collisions subtract with an explanation each time.</td></tr><tr><td><b>Letter-grade debrief</b></td><td class="tag-l">Summative</td><td>All</td><td>Per-module toast with grade, collision count, and the one habit to fix next flight.</td></tr></table>`,
   "Performance Support Assets":`<div class="row3"><div class="mini-card"><div class="ic">&#128202;</div><h4>Telemetry HUD + warnings</h4><p>Colour-coded cards and plain-language warning pills escalate before an emergency, mirroring real ground-station UIs.</p></div><div class="mini-card"><div class="ic">&#10067;</div><h4>Controls &amp; help overlay</h4><p>Full keyboard/gamepad reference one keypress away (?), plus a skippable first-flight onboarding.</p></div><div class="mini-card"><div class="ic">&#127911;</div><h4>Procedural audio cues</h4><p>Spool-up, landing thuds, objective chimes, and distinct alert tones — information through a second channel, mutable.</p></div></div>`,
   "Accessibility Considerations":`<div class="a11y"><div><span class="ck">&#10003;</span> Fully keyboard-operable — a gamepad is recommended, never required.</div><div><span class="ck">&#10003;</span> Reduced-motion toggle calms UI animation and the drone's hover bob; <i>prefers-reduced-motion</i> honoured.</div><div><span class="ck">&#10003;</span> Feedback is never sound-alone or colour-alone — every audio cue has a visual twin (pills, flashes, feed entries).</div><div><span class="ck">&#10003;</span> Mute and volume controls; audio initialises only after a user gesture (autoplay-safe).</div><div><span class="ck">&#10003;</span> Preferences persist in localStorage across sessions.</div><div><span class="ck">&#10003;</span> Honest scope: civilian training abstraction — excludes weaponised, surveillance, and unauthorized-operation use cases.</div></div>`,
   "Prototype Screens":`<div class="proto"><div class="device"><div class="scr"><div class="hd"><span class="dt">Pitch</span><span class="dp">M02</span></div><div class="choice sel">Ring 2 cleared &#10003; · ALT 2.2m</div><div class="choice">Feed: "nose dips, then moves"</div></div><div class="cap">Input &#8594; Physics &#8594; Explanation</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Battery 11%</span><span class="dp">RTH</span></div><div class="choice">Fight the controls</div><div class="choice sel">Let the failsafe land it &#10003;</div></div><div class="cap">Failure scenario</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Debrief</span><span class="dp">Grade</span></div><div class="choice sel">Stability 88/100 · B</div><div class="choice">1 collision — widen clearance</div></div><div class="cap">Letter-grade debrief</div></div></div>`,
   "Success Metrics":`<div class="metric-grid"><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">module completion across the 12-module arc</div><div class="k">Kirkpatrick L2</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">stability score on repeat attempts</div><div class="k">L2 · skill curve</div></div><div class="mc"><div class="mtgt">&#8595; reduce</div><div class="l">collisions and hard landings per sortie</div><div class="k">L2 · behavior</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">correct failsafe response (yield to RTH)</div><div class="k">L3 · transfer intent</div></div></div><div class="note"><b>&#9656;</b> Design targets — arrows show the direction of success. No results are claimed; figures pending learner pilots.</div>`,
   "Reflection & Lessons Learned":`<div class="reflect"><p><b>What worked:</b> Making the simulation explain itself — the input-edge explanation feed — turned a 3D toy into a teacher, and solid obstacles plus a scored failsafe turned safety from copy into consequence.</p><p><b>What I'd change:</b> The physics is a training abstraction tuned for learning clarity, not flight-model accuracy; a Rapier-based model behind the same lessons is the natural next step, along with recorded flight playback for debriefs.</p><p><b>The transferable lesson:</b> In simulation-based learning, the explanation layer is the product. The 3D scene earns attention; the feed, the telemetry, and the debrief do the teaching.</p></div>`
  }},
 "p-turbine":{
  title:"Gas Turbine — 3D Interactive Tutorial",
  sub:"A browser-based 360° cutaway that teaches the anatomy and gas path of a heavy-duty gas turbine — rotate it, strip the casing, and click any component to learn what it does and why it matters. Built in Three.js as an original-geometry training model.",
  facts:[["Role","LXD + 3D interactive build"],["Audience","Power-gen trainees & engineering students"],["Domain","Energy · rotating equipment"],["Mode","Web 3D tutorial · Three.js · single-file"]],
  thumbClass:"t-turbine",
  body:{
   "Project Overview":`<div style="display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px"><a class="btn btn-primary" href="https://gas-turbine-3d-tutorial.vercel.app/" target="_blank" rel="noopener">&#9654; Open the live tutorial</a><a class="btn btn-ghost" href="https://github.com/AkhilDhruva/Gas-Turbine-3D-Interactive-Tutorial" target="_blank" rel="noopener">View source on GitHub</a></div><p>A built, interactive 3D tutorial: a real-time cutaway of an axial-flow heavy-duty gas turbine you can spin a full 360&deg;, zoom into, and strip to the internals. Ten hotspots walk the gas path from air inlet to exhaust diffuser, each opening a plain-language explanation and a small spec card. <b>Illustrative training model — original geometry, not a manufacturer asset; a familiarization aid, not a maintenance or certification course.</b></p><div class="row3"><div class="mini-card"><div class="ic">&#128260;</div><h4>Explore, don't read</h4><p>Free 360&deg; rotation and a casing toggle turn a sealed machine into something a learner can open and orbit.</p></div><div class="mini-card"><div class="ic">&#128205;</div><h4>Part-by-part, in context</h4><p>Each hotspot teaches one component where it actually sits — compressor, combustor, turbine, diffuser.</p></div><div class="mini-card"><div class="ic">&#10145;</div><h4>Follow the energy</h4><p>Cold air in at the left, hot gas out at the right — the gas path is the spine of the whole tour.</p></div></div>`,
   "Business Problem":`<p>A heavy-duty gas turbine is large, sealed, and runs at temperatures and speeds that make it impossible to open up for teaching. New technicians, engineering students, and technical staff are expected to understand a machine they can never take apart — and static cutaway posters flatten a deeply three-dimensional, nested assembly into lines on a page.</p><p><b>The metric at risk:</b> time-to-familiarity during onboarding, and the comprehension errors that follow when someone can't picture how the compressor, combustor, and turbine share one shaft. The gap is mental model, not motivation.</p>`,
   "Learner Problem":`<ul class="obj"><li><span class="lvl">Spatial</span><span><b>The arrangement is invisible</b> — it's hard to see that compressor, combustor, and turbine nest along a single rotor, or how the casing wraps the blade path.</span></li><li><span class="lvl">Vocabulary</span><span><b>The words are abstract</b> — stator, transition piece, diffuser, can-annular mean little without the object in front of you.</span></li><li><span class="lvl">Cause</span><span><b>The energy story is counter-intuitive</b> — that well over half the turbine's output is spent just driving its own compressor surprises most beginners.</span></li></ul>`,
   "Target Audience":`<p>Entry-level power-generation technicians, mechanical and energy-engineering students, and technical onboarding or sales staff who need a working mental model of how a gas turbine is built and how it works. Assumes no turbomachinery background, runs in any modern browser with no install, and works on desktop (drag + scroll) and touch (drag + pinch).</p>`,
   "Learning Objectives":`<ul class="obj"><li><span class="lvl">Identify</span><span>Name the major sections and components in order along the gas path, from air inlet to exhaust diffuser.</span></li><li><span class="lvl">Explain</span><span>State the function of each component — compression, combustion, expansion, and pressure recovery.</span></li><li><span class="lvl">Trace</span><span>Describe the flow of air and energy through the machine, and why the compressor consumes most of the turbine's work.</span></li><li><span class="lvl">Appreciate</span><span>Recognise why the hot section is the hard part — firing temperature, blade cooling, thermal-barrier coatings, and single-crystal alloys.</span></li></ul>`,
   "Instructional Strategy":`<div class="row2"><div class="mini-card"><div class="ic">&#128260;</div><h4>Manipulation before explanation</h4><p>Learners rotate and zoom the whole machine first; curiosity about a part precedes the text about it.</p></div><div class="mini-card"><div class="ic">&#128205;</div><h4>One component at a time</h4><p>A hotspot opens a single focused micro-explanation plus a two-row spec card — no walls of text.</p></div><div class="mini-card"><div class="ic">&#128065;</div><h4>Reveal the internals</h4><p>The casing toggle strips the housing so the outside-to-inside relationship becomes obvious, not assumed.</p></div><div class="mini-card"><div class="ic">&#128214;</div><h4>Linear tour on demand</h4><p>Prev / Next step through the components in gas-path order for learners who want a guided path.</p></div></div>`,
   "Content Architecture":`<p>Ten hotspots organised in gas-path order — the same left-to-right journey the air takes through the machine.</p><div class="arch"><div class="arch-tier"><div class="at"><span class="badge">Cold</span> Air in &amp; compress</div><div class="mods"><span class="mod">Air inlet &amp; nose cone</span><span class="mod">Axial compressor</span><span class="mod">Blades &amp; stators</span><span class="mod">Rotor shaft</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Burn</span> Add fuel &amp; ignite</div><div class="mods"><span class="mod">Fuel nozzles</span><span class="mod">Can-annular combustor</span><span class="mod">Transition piece</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Hot</span> Expand &amp; extract</div><div class="mods"><span class="mod">Turbine section</span><span class="mod">Cooled turbine blades</span></div></div><div class="arch-tier"><div class="at"><span class="badge">Out</span> Recover &amp; exhaust</div><div class="mods"><span class="mod">Exhaust diffuser</span></div></div></div>`,
   "Storyboard Samples":`<div class="story-grid">${frame("Hotspot · Axial Compressor","Click to inspect","The machine is mid-rotation; a pulsing + marker sits on the compressor. Clicking it slides in a panel.","'A multi-stage axial compressor squeezes incoming air to roughly 20–23 times atmospheric pressure before combustion.'","Click the marker; the side panel opens with the explanation and a Stages / Pressure-ratio spec card.")}${frame("Casing toggle","Strip the housing","Learner taps the Casing button; the outer casing shells fade out to expose blades, cans, and the rotor drum.","'The housing hides the work — drop it and the blade rows and combustor cans you just read about appear in place.'","Toggle Casing off, rotate to the cutaway window, then step Next through the internals.","w80")}</div>`,
   "Interaction Design Decisions":`<ul class="obj"><li><span class="lvl">Why</span><span><b>The casing is a cutaway, not just hideable</b> — an 83&deg; window is carved out of every shell so internals stay visible even with the housing on.</span></li><li><span class="lvl">Why</span><span><b>Hotspots fade on the far side</b> — markers behind the machine dim and stop catching clicks, so you only interact with parts you can actually see.</span></li><li><span class="lvl">Why</span><span><b>DOM markers over in-scene sprites</b> — real &lt;button&gt; elements with aria-labels make each hotspot a proper, labelled control, not a painted dot.</span></li><li><span class="lvl">Why</span><span><b>Every part carries a two-row spec card</b> — one explanation plus two hard numbers keeps each stop quick to scan and easy to remember.</span></li><li><span class="lvl">Why</span><span><b>Original geometry, stated up front</b> — the model is built from primitives to teach honestly, with a standing note that it is not a manufacturer asset.</span></li></ul>`,
   "Assessment Strategy":`<p>Version one is a familiarization tutorial — exploration and a guided tour, with no scored assessment yet. That is stated plainly rather than dressed up.</p><table class="tbl"><tr><th>Layer</th><th>Type</th><th>Objective</th><th>Status</th></tr><tr><td><b>Guided component tour</b></td><td class="tag-l">Formative</td><td>Identify / Explain</td><td>Live — Prev / Next walk every component in gas-path order.</td></tr><tr><td><b>Spec-card recall</b></td><td class="tag-l">Self-check</td><td>Explain</td><td>Live — each part pairs a function with two memorable figures.</td></tr><tr><td><b>Drag-to-label knowledge check</b></td><td class="tag-l">Summative</td><td>Identify</td><td><b style="color:var(--amber)">Planned</b> — the honest next layer before any mastery claim.</td></tr></table>`,
   "Performance Support Assets":`<div class="row3"><div class="mini-card"><div class="ic">&#128203;</div><h4>Per-part spec cards</h4><p>A quick-reference function and two key figures for every component, available the moment it's selected.</p></div><div class="mini-card"><div class="ic">&#128065;</div><h4>Casing toggle</h4><p>A study tool in its own right — flip between the external machine and the exposed internals at will.</p></div><div class="mini-card"><div class="ic">&#128260;</div><h4>Reset &amp; auto-rotate</h4><p>One button restores the framed view; gentle auto-rotation invites exploration without demanding it.</p></div></div>`,
   "Accessibility Considerations":`<p>Accessibility is the documented next iteration on this build — stated honestly rather than overclaimed.</p><div class="a11y"><div><span class="ck">&#10003;</span> Hotspots are real &lt;button&gt; elements with descriptive aria-labels.</div><div><span class="ck">&#10003;</span> Pointer, touch (drag &amp; pinch), and scroll-wheel input are all supported.</div><div><span class="ck">&#10003;</span> High-contrast labels and panel text over a light, glare-managed background.</div><div><span class="ck" style="color:var(--amber)">&#9711;</span> In progress: keyboard rotation, zoom, and focus-visible for the canvas and hotspots.</div><div><span class="ck" style="color:var(--amber)">&#9711;</span> In progress: prefers-reduced-motion to calm auto-rotate and the marker pulse.</div><div><span class="ck" style="color:var(--amber)">&#9711;</span> In progress: a non-3D text fallback listing every component and its description.</div></div><p style="font-size:14px;color:var(--muted)">A WebGL tutorial that claims accessibility has to be honest about the keyboard and reduced-motion gaps — they're scoped and next, not done.</p>`,
   "Prototype Screens":`<div class="proto"><div class="device"><div class="scr"><div class="hd"><span class="dt">Compressor</span><span class="dp">3 / 10</span></div><div class="choice sel">17 axial stages</div><div class="choice">~20–23 : 1 pressure ratio</div></div><div class="cap">Hotspot + spec card</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Casing</span><span class="dp">off</span></div><div class="choice sel">Internals exposed &#10003;</div><div class="choice">Cans · blades · rotor drum</div></div><div class="cap">Cutaway reveal</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Combustor</span><span class="dp">Hot</span></div><div class="choice sel">16 cans · ~1,600 &deg;C</div><div class="choice">Dry Low-NOx nozzles</div></div><div class="cap">Hot-section stop</div></div></div>`,
   "Success Metrics":`<div class="metric-grid"><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">components correctly identified on a follow-up check</div><div class="k">Kirkpatrick L2</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">self-rated familiarity, pre &#8594; post</div><div class="k">L1 · confidence</div></div><div class="mc"><div class="mtgt">&#8595; reduce</div><div class="l">onboarding time to "can name the gas path"</div><div class="k">L2 · efficiency</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">hotspot coverage per session</div><div class="k">L2 · engagement</div></div></div><div class="note"><b>&#9656;</b> Design targets — arrows show the direction of success. No results are claimed; figures pending a learner pilot. Engineering figures in the tutorial are representative of the J/JAC class <b style="color:var(--amber)">[VERIFY WITH SME]</b>.</div>`,
   "Reflection & Lessons Learned":`<div class="reflect"><p><b>What worked:</b> Letting learners strip the casing and orbit the machine made the spatial arrangement click in a way a flat cutaway never does — the gas path stops being a diagram and becomes a place.</p><p><b>What I'd change:</b> A drag-to-label knowledge check and a real keyboard / reduced-motion accessibility pass are the honest next steps before this earns a mastery or AA claim.</p><p><b>The transferable lesson:</b> For complex hardware, the interaction is the explanation. Rotating, revealing, and inspecting carry the teaching; the text just names what the learner already discovered.</p></div>`
  }},
 "p-datacenter":{
  title:"Data Center Technician Upskilling",
  sub:"A three-program upskilling suite that takes a new hire from \"never been on the floor\" to trusted on a 24×7 shift — grounded in real standards (EIA-310-D, ASHRAE TC9.9, Uptime / TIA-942-C, ITIL), built in Storyline 360 / Rise 360, and accelerated with an AI production pipeline and a custom interactive 3D rack.",
  facts:[["Role","Technical ID + LXD + 3D build"],["Audience","New data-center technicians"],["Domain","Data center operations · upskilling"],["Mode","Storyline/Rise · SCORM/xAPI · Three.js"]],
  thumbClass:"t-datacenter",
  body:{
   "Project Overview":`<div style="display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px"><a class="btn btn-primary" href="https://data-center-training.vercel.app" target="_blank" rel="noopener">&#9654; Open the interactive 3D rack</a></div><p>A stackable, three-program upskilling <b>suite</b> that takes a new hire from "never been on the floor" to trusted on a 24&times;7 shift — grounded in real standards (EIA-310-D, ASHRAE TC9.9, Uptime / TIA-942-C, ITIL), built in Storyline 360 / Rise 360, and accelerated with an AI production pipeline. The middle program is built to full production depth, and the showpiece is an interactive 3D 42U rack you can open in any browser. <b>A portfolio training concept — market figures are cited; learning outcomes are design targets to validate in a pilot.</b></p><div class="row3"><div class="mini-card"><div class="ic">&#129513;</div><h4>A three-program ladder</h4><p>Operate the Environment &#8594; Rack to Runtime &#8594; Defend the Uptime — each course's exit is the next one's entry.</p></div><div class="mini-card"><div class="ic">&#11088;</div><h4>Flagship built to depth</h4><p>"Rack to Runtime" ships block-by-block copy, two branching scored scenarios, a quiz, and a Rise assembly runbook.</p></div><div class="mini-card"><div class="ic">&#128421;</div><h4>Interactive 3D rack</h4><p>A rotatable, clickable 42U rack with Power and Airflow views, built to EIA-310-D dimensions and embeddable in Rise.</p></div></div>`,
   "Business Problem":`<p>The AI build-out has created one of the strongest structural skills shortages in any US sector — and the bottleneck isn't hardware, it's <b>trained people</b>. The market research grounding this project:</p><ul class="obj"><li><span class="lvl">Gap</span><span>A projected <b>140,000+ skilled-worker gap by 2030</b> in data-center operations as experienced technicians retire faster than new ones are trained <i>(Johnson Controls, via Data Center Knowledge)</i>.</span></li><li><span class="lvl">Growth</span><span>US data-center construction growing from <b>$48.18B (2024) to $112.33B (2030)</b> — a 15.15% CAGR <i>(Arizton)</i>.</span></li><li><span class="lvl">Hiring</span><span>Nearly <b>half of operators (46%)</b> report difficulty finding qualified candidates <i>(Uptime Institute Global Data Center Survey)</i>.</span></li></ul><p>The fastest-to-scale layer of that training is exactly the <b>knowledge / procedure</b> layer great e-learning owns: how a facility stays available, how to install and commission to spec, how to triage and escalate at 2 a.m.</p>`,
   "Learner Problem":`<ul class="obj"><li><span class="lvl">No floor time</span><span><b>A new hire has never been on the floor</b> — racks, aisles, and the power / cooling path are abstractions until they can see and handle them.</span></li><li><span class="lvl">Procedure</span><span><b>SOP / MOP / EOP are just acronyms</b> — knowing when to follow a method of procedure and when to call a hold is judgment that shadowing teaches slowly and unevenly.</span></li><li><span class="lvl">Pressure</span><span><b>The 2 a.m. alarm is unrehearsed</b> — triaging a P1&#8211;P4 event, escalating correctly, and handing off cleanly is high-stakes and rarely practiced before it's real.</span></li></ul>`,
   "Target Audience":`<p>New data-center technicians and operations hires — many with no prior floor experience — plus the shift leads and onboarding programs responsible for getting them to competency. Delivered through the LMS via SCORM 1.2 / xAPI, responsive for desktop and tablet, with the 3D rack running in any modern browser.</p>`,
   "Learning Objectives":`<p>Bloom-tagged terminal and enabling objectives — and <b>every objective maps to an assessment item</b> (no orphan content, no unassessed objective).</p><ul class="obj"><li><span class="lvl">Operate</span><span>Apply data-center fundamentals — the Tier model, ASHRAE thermal envelope, SOP / MOP / EOP, and floor safety — to work safely from day one.</span></li><li><span class="lvl">Install</span><span>Install and commission a rack to spec, following the MOP and its hold points from dock to live.</span></li><li><span class="lvl">Decide</span><span>Make a defensible commissioning go / no-go call, treating a justified hold as the correct outcome.</span></li><li><span class="lvl">Defend</span><span>Monitor a live shift, triage P1&#8211;P4 events, escalate on time, and hand off cleanly.</span></li></ul>`,
   "Instructional Strategy":`<div class="row2"><div class="mini-card"><div class="ic">&#128260;</div><h4>ADDIE backbone, SAM iteration</h4><p>A three-program ladder architected so each course's exit competency is the next one's entry.</p></div><div class="mini-card"><div class="ic">&#127807;</div><h4>Productive failure</h4><p>Wrong choices show honest consequences and route back; calling a hold or Stop <i>scores as a win</i>, not a dead end.</p></div><div class="mini-card"><div class="ic">&#128209;</div><h4>One cited source of truth</h4><p>A spec library is the single source; safety and spec wording stays verbatim, never AI-paraphrased, with SME sign-off as a gate.</p></div><div class="mini-card"><div class="ic">&#127916;</div><h4>Mayer multimedia principles</h4><p>Narration complements on-screen text, one idea per screen, and the critical number is signalled.</p></div></div>`,
   "Content Architecture":`<p>A stackable, three-program suite — a ladder where each program's exit competency is the next one's entry. The middle program is built to full production depth in this package; the other two are designed and outlined.</p><div class="arch"><div class="arch-tier"><div class="at"><span class="badge">P1</span> Operate the Environment</div><div class="mods"><span class="mod">Tiers &amp; TIA-942</span><span class="mod">ASHRAE thermal</span><span class="mod">SOP / MOP / EOP</span><span class="mod">Floor safety</span><span class="mod">Designed + outlined</span></div></div><div class="arch-tier"><div class="at"><span class="badge">P2 &#11088;</span> Rack to Runtime &mdash; fully built</div><div class="mods"><span class="mod">Rack specs (EIA-310-D)</span><span class="mod">Install MOP</span><span class="mod">Commissioning go/no-go</span><span class="mod">First-night alarm</span><span class="mod">Quiz + runbook</span></div></div><div class="arch-tier"><div class="at"><span class="badge">P3</span> Defend the Uptime</div><div class="mods"><span class="mod">Monitor the shift</span><span class="mod">Triage P1&#8211;P4</span><span class="mod">Escalate</span><span class="mod">Clean hand-off</span><span class="mod">Designed + outlined</span></div></div></div>`,
   "Storyboard Samples":`<div class="story-grid">${frame("P2 · Commissioning","Go / no-go call","The rack is installed; a checklist shows one power feed reading out of tolerance against the MOP spec.","'Two independent feeds should read within tolerance before you energise. One doesn't. What's your call?'","Choose Energise vs. Call a hold; calling the hold on the failed feed scores as the correct, safe outcome.")}${frame("P2 · First night","P1 alarm triage","2 a.m. — a high-temperature alarm fires on the new rack; several signals compete for attention.","'A P1 just came in. Work the priority, not the noise — what do you check, who do you call, and when?'","Triage the P1, escalate within the target window, and hand off; latency and missed signals are tracked.","w80")}</div>`,
   "Interaction Design Decisions":`<ul class="obj"><li><span class="lvl">Why</span><span><b>Calling a hold scores as a win</b> — in a safety-critical domain, rewarding "stop when unsure" trains the instinct the floor actually needs.</span></li><li><span class="lvl">Why</span><span><b>Spec and safety wording is verbatim</b> — the cited spec library is the single source of truth; facts are locked once and never AI-paraphrased, with SME sign-off as a gate.</span></li><li><span class="lvl">Why</span><span><b>The 3D rack is a reusable web object</b> — one Three.js asset built to EIA-310-D embeds into Rise and stands alone in a browser, so the spatial model is consistent everywhere.</span></li><li><span class="lvl">Why</span><span><b>Scored sims live in Storyline</b> — variables and branching drive the go/no-go and alarm scenarios; responsive content and knowledge checks live in Rise.</span></li><li><span class="lvl">Why</span><span><b>Sims track meaningful metrics</b> — missed-P1, escalation latency, and clean-commission are captured to xAPI, not just a completion tick.</span></li></ul>`,
   "Assessment Strategy":`<p>Knowledge checks plus scored branching sims, delivered to the LMS over SCORM 1.2 / xAPI — with every objective mapped to an assessment item.</p><table class="tbl"><tr><th>Assessment</th><th>Type</th><th>Objective</th><th>Measures</th></tr><tr><td><b>Verbatim quiz bank</b></td><td class="tag-l">Knowledge</td><td>Operate / Install</td><td>Recall of specs, tiers, and procedure drawn from the cited source library.</td></tr><tr><td><b>Commissioning go/no-go</b></td><td class="tag-l">Scored sim</td><td>Decide</td><td>Whether the learner energises unsafely or calls the justified hold.</td></tr><tr><td><b>First-night alarm</b></td><td class="tag-l">Scored sim</td><td>Defend</td><td>P1 handling, escalation latency, and clean hand-off, tracked to xAPI.</td></tr></table>`,
   "Performance Support Assets":`<div class="row3"><div class="mini-card"><div class="ic">&#128421;</div><h4>Interactive 3D 42U rack</h4><p>Rotatable and clickable, with Power and Airflow views to EIA-310-D — a job aid and a teaching object in one, embeddable in Rise.</p></div><div class="mini-card"><div class="ic">&#128209;</div><h4>Cited spec library</h4><p>A single source of truth for racks, tiers, thermal, power, ops, and escalation — SME-verified and reused across all three programs.</p></div><div class="mini-card"><div class="ic">&#128736;</div><h4>MOP &amp; Rise runbook</h4><p>The install method-of-procedure with hold points, plus an assembly runbook so the flagship imports cleanly into Rise.</p></div></div>`,
   "Accessibility Considerations":`<p>WCAG 2.1 AA is built into the course design — with the interactive 3D asset's full keyboard pass called out honestly as the verification item.</p><div class="a11y"><div><span class="ck">&#10003;</span> Real-text data (never text baked into images), with alt text on visuals and captions on narration.</div><div><span class="ck">&#10003;</span> Keyboard-operable with visible focus across the Rise / Storyline content.</div><div><span class="ck">&#10003;</span> Status shown by text + icon, never colour alone; reduced-motion respected.</div><div><span class="ck">&#10003;</span> Assessment feedback is specific and text-based, not colour- or sound-dependent.</div><div><span class="ck" style="color:var(--amber)">&#9711;</span> In progress: full keyboard operation and a text fallback for the interactive 3D rack web object.</div></div>`,
   "Prototype Screens":`<div class="proto"><div class="device"><div class="scr"><div class="hd"><span class="dt">3D Rack</span><span class="dp">Airflow</span></div><div class="choice sel">Cold aisle &#8594; hot aisle</div><div class="choice">42U · EIA-310-D</div></div><div class="cap">Interactive 3D rack</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">Commission</span><span class="dp">Go/No-go</span></div><div class="choice">Energise the rack</div><div class="choice sel">Call a hold &#10003;</div></div><div class="cap">Scored decision</div></div><div class="device"><div class="scr"><div class="hd"><span class="dt">2 a.m.</span><span class="dp">P1</span></div><div class="choice sel">Escalate on time &#10003;</div><div class="choice">Chase the noise</div></div><div class="cap">Alarm triage</div></div></div>`,
   "Success Metrics":`<div class="metric-grid"><div class="mc"><div class="mtgt">&#8595; reduce</div><div class="l">time-to-competency / new-tech ramp time</div><div class="k">Kirkpatrick L3</div></div><div class="mc"><div class="mtgt">&#8595; reduce</div><div class="l">procedural incidents on the floor</div><div class="k">L4 · business</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">clean commissions &amp; on-time escalations</div><div class="k">L3 · behavior</div></div><div class="mc"><div class="mtgt">&#8593; improve</div><div class="l">onboarding &amp; audit consistency</div><div class="k">L4 · ops</div></div></div><div class="note"><b>&#9656;</b> Design targets — arrows show the direction of success. No results are claimed; these are the business case to validate in a pilot. Market figures are cited to Johnson Controls / Arizton / Uptime Institute.</div>`,
   "Reflection & Lessons Learned":`<div class="reflect"><p><b>What worked:</b> Locking every fact once in a cited, SME-verified spec library — then projecting storyboard, scenarios, quiz, and asset specs from it — kept a technically dense build accurate and fast, and the interactive 3D rack turned rack anatomy from a diagram into something a learner can handle.</p><p><b>What I'd change:</b> P1 and P3 are designed and outlined but not yet built to the flagship's depth, and the 3D rack still needs its full keyboard pass — both are the honest next steps.</p><p><b>The transferable lesson:</b> For a hard technical domain, rigor and speed aren't opposites. A single cited source of truth plus an AI production pipeline let one deep, interactive flagship stand in for a pile of thin samples — which is exactly the bar the work is built to.</p></div>`
  }}
};
